const SOURCE='../content-source/phase-1-8-canonical-objects.json.gz.b64';
const originalFetch=window.fetch.bind(window);
let cachedText=null;
function decodeBase64(text){const clean=text.replace(/\s+/g,'');const chunk=32768;const parts=[];for(let i=0;i<clean.length;i+=chunk){const binary=atob(clean.slice(i,i+chunk));const bytes=new Uint8Array(binary.length);for(let j=0;j<binary.length;j++)bytes[j]=binary.charCodeAt(j);parts.push(bytes)}const total=parts.reduce((n,p)=>n+p.length,0);const all=new Uint8Array(total);let offset=0;for(const p of parts){all.set(p,offset);offset+=p.length}return all}
async function loadSource(){if(cachedText)return cachedText;const response=await originalFetch(`${SOURCE}?v=2.0.0`,{cache:'no-store'});if(!response.ok)throw new Error(`Canonical source returned ${response.status}`);const encoded=await response.text();const compressed=decodeBase64(encoded);if(!('DecompressionStream'in window))throw new Error('This browser does not support gzip decompression.');const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));const text=await new Response(stream).text();const payload=JSON.parse(text);if(!Array.isArray(payload.records)||payload.records.length!==487)throw new Error(`Expected 487 canonical records; received ${payload.records?.length??0}.`);cachedText=text;return text}
window.fetch=async function(input,init){const url=typeof input==='string'?input:input.url;if(url.endsWith('./data/content.json')||url.endsWith('/v2/data/content.json')){try{return new Response(await loadSource(),{status:200,headers:{'content-type':'application/json'}})}catch(error){return new Response(JSON.stringify({error:error.message,records:[]}),{status:500,headers:{'content-type':'application/json'}})}}return originalFetch(input,init)};
import('./app.js');